use core::borrow::BorrowMut;
use core::fmt::{self, Debug, Display};
use core::hash::Hash;
use core::mem::ManuallyDrop;
use core::num::NonZero;
#[cfg(not(target_has_atomic = "64"))]
use core::sync::atomic::AtomicU32;
#[cfg(target_has_atomic = "64")]
use core::sync::atomic::AtomicU64;
use core::sync::atomic::{self};

use crate::{Descriptor, DynHandler, Handler, LogArgs, Logger, SharedHandler};

/// Identifier for a span.
///
/// Span IDs can be generated by [`BaseHandler::generate_span_id`].
/// They are not reused by the same handler until its span ID counter wraps.
/// After wrap-around, previously issued IDs may be reused.
///
/// [`BaseHandler::generate_span_id`]: crate::BaseHandler::generate_span_id
#[derive(Copy, Clone, Eq, PartialEq, Ord, PartialOrd, Hash, Debug)]
pub struct SpanId(
    /// The non-zero numeric span identifier.
    pub NonZero<u64>,
);

/// A thread-safe generator of [`SpanId`] values.
///
/// Wraps a relaxed atomic counter and skips `0`.
/// On targets with 64-bit atomics the counter is `AtomicU64`.
/// On targets without them it falls back to `AtomicU32`.
///
/// Share one instance across every handler that must produce interoperating
/// IDs.
#[derive(Debug)]
pub struct SpanIdGenerator(SpanIdGeneratorAtomic);

#[cfg(target_has_atomic = "64")]
type SpanIdGeneratorAtomic = AtomicU64;
#[cfg(not(target_has_atomic = "64"))]
type SpanIdGeneratorAtomic = AtomicU32;

/// The kind of a span, describing how the span's lifetime relates to
/// its creator's.
///
/// The "creator" is whatever `Handler::enter_span` was called on to
/// produce this span:
///
/// - the raw handler, for a root span;
/// - another span, for a span created via [`LoggerExt::borrowing_span`] on that
///   span;
/// - the span identified by a [`DetachedLogger`]'s [`Logger::span_id`], for a
///   span created from a detached context. The context is a proxy, so the
///   creator from the backend's perspective is the original span, potentially
///   on another thread or task.
///
/// The kind is reported to [`Handler::enter_span`] and
/// [`DynHandler::exit_span`] so backends can track open spans
/// correctly.
/// It tells the backend whether the creator is guaranteed to remain open and
/// quiet while this span is active, or whether the creator may emit events and
/// exit at any time.
///
/// # Per-link
///
/// The kind is per-link: it describes this span's relationship to its direct
/// creator only.
/// A [`Nested`] child of a [`Detached`] span is still `Nested` — it is blocked
/// relative to its parent even though its parent is not blocked relative to its
/// own parent.
///
/// # Not the same as `Logger::child_borrowing_span_kind`
///
/// [`SpanKind`] describes a span's relationship to its creator.
/// [`Logger::child_borrowing_span_kind`] describes the relationship a
/// **future** child of a logger will have to that logger.
/// The two answer different questions.
/// An [`OwningSpan`] is entered with [`SpanKind::Detached`], yet
/// [`Logger::child_borrowing_span_kind`] on the same [`OwningSpan`] returns
/// [`SpanKind::Nested`] because children borrow the owning span mutably.
///
/// [`Nested`]: Self::Nested
/// [`Detached`]: Self::Detached
/// [`SpanKind::Nested`]: Self::Nested
/// [`SpanKind::Detached`]: Self::Detached
/// [`OwningSpan`]: crate::OwningSpan
/// [`Logger::span_id`]: crate::Logger::span_id
/// [`Logger::child_borrowing_span_kind`]: crate::Logger::child_borrowing_span_kind
/// [`LoggerExt::borrowing_span`]: crate::LoggerExt::borrowing_span
#[derive(Copy, Clone, Eq, PartialEq, Ord, PartialOrd, Hash, Debug)]
pub enum SpanKind {
    /// A span that blocks its creator for its entire lifetime.
    ///
    /// The span borrows its creator's handler mutably, so the creator cannot
    /// emit events or exit until the span is dropped.
    ///
    /// Backends may rely on:
    /// - The creator's `exit_span` is emitted strictly after this span's
    ///   `exit_span`.
    /// - Every event from this span falls between the creator's `enter_span`
    ///   and `exit_span`.
    /// - A stack of open spans is well-formed: when this span exits, its
    ///   creator (if any) is still on the stack.
    ///
    /// A root span on a raw handler is also `Nested`.
    /// The creator in that case is the handler itself, which is blocked even
    /// though there is no parent span to block.
    Nested,

    /// A span that does not block its creator.
    ///
    /// The span holds a cloned handler, obtained via
    /// [`LoggerExt::owning_span`], via [`DeferredSpan::enter`], or via
    /// [`LoggerExt::borrowing_span`] on a [`DetachedLogger`], so the creator
    /// may emit events and exit while the span is still active.
    ///
    /// Backends must not assume:
    /// - The creator's `exit_span` comes after this span's `exit_span`. It may
    ///   come before, between, or after.
    /// - Events from this span and from the creator are ordered relative to
    ///   each other. They may interleave arbitrarily.
    /// - The creator is still open when this span's events arrive.
    ///
    /// This span's own children are reported as [`Nested`]: they borrow this
    /// span's handler mutably and therefore cannot outlive it, even though this
    /// span itself may outlive its creator.
    ///
    /// [`Nested`]: Self::Nested
    /// [`LoggerExt::detach`]: crate::LoggerExt::detach
    /// [`LoggerExt::owning_span`]: crate::LoggerExt::owning_span
    /// [`LoggerExt::borrowing_span`]: crate::LoggerExt::borrowing_span
    Detached,
}

/// An active span that borrows a handler and emits its exit event on drop.
///
/// `BorrowingSpan` represents a span whose [`Handler::enter_span`] has already
/// been emitted.
/// It is returned by [`LoggerExt::borrowing_span`] and
/// [`LoggerExt::transparent_borrowing_span`], including when called on a
/// [`DetachedLogger`] to materialize it. A `BorrowingSpan` borrows the handler
/// and must be dropped before the handler is used again.
/// On drop it emits [`DynHandler::exit_span`] with its stored [`SpanKind`],
/// unless the span is transparent or [`forget`](Self::forget) has been called.
///
/// `BorrowingSpan` implements [`Logger`], so events logged through it and
/// child spans created from it are attributed to its [`SpanId`].
///
/// A transparent span is created by [`LoggerExt::transparent_borrowing_span`]
/// or [`BorrowingSpan::transparent`], carries no descriptor, and emits no
/// events. [`forget`] converts a regular span into a transparent one without
/// affecting child spans that were already created from it.
/// A transparent span inherits its kind from the logger that produced it: a
/// transparent span from a `DetachedLogger` will produce `Detached` children,
/// and a transparent span from any other logger will produce `Nested` children
///
/// [`LoggerExt::borrowing_span`]: crate::LoggerExt::borrowing_span
/// [`LoggerExt::transparent_borrowing_span`]: crate::LoggerExt::transparent_borrowing_span
/// [`forget`]: Self::forget
#[must_use = "if unused, the span will be immediately closed"]
#[derive(Eq, PartialEq, Ord, PartialOrd, Hash, Debug)]
pub struct BorrowingSpan<'a, H>
where
    H: ?Sized + DynHandler<()>,
{
    handler: &'a mut H,
    descriptor: Option<&'static Descriptor>,
    id: Option<SpanId>,
    kind: SpanKind,
}

/// An active span that owns a handler and emits its exit event on drop.
///
/// `OwningSpan` represents a span whose [`Handler::enter_span`] has already
/// been emitted, but which owns its handler rather than borrowing it.
/// It is returned by [`DeferredSpan::enter`], including internally by
/// [`PollInstrumented::new`]. Because it owns the handler, it can be stored in
/// a struct or moved into a future without holding a borrow of the original
/// logger.
/// On drop it emits [`DynHandler::exit_span`] with [`SpanKind::Detached`] on
/// drop, unless the [`forget`] has been called.
///
/// `OwningSpan` implements [`Logger`], so events logged through it and child
/// spans created from it are attributed to its [`SpanId`].
///
/// A transparent span is created by [`OwningSpan::transparent`], carries no
/// descriptor, and emits no events.
/// [`forget`] converts a regular span into a transparent one without affecting
/// child spans that were already created from it.
///
/// [`forget`]: Self::forget
/// [`PollInstrumented::new`]: crate::PollInstrumented::new
#[must_use = "if unused, the span will be immediately closed"]
#[derive(Eq, PartialEq, Ord, PartialOrd, Hash, Debug)]
pub struct OwningSpan<H>
where
    H: DynHandler<()>,
{
    handler: H,
    descriptor: Option<&'static Descriptor>,
    id: Option<SpanId>,
}

/// A span whose materialization is deferred until an explicit
/// [`enter`](Self::enter) call.
///
/// A `DeferredSpan` owns a cloned handler, the future span's [`Descriptor`],
/// a lazy argument factory, and the parent [`SpanId`] of the logger it was
/// created from.
/// It emits no events on creation or drop, and is created by
/// [`LoggerExt::deferred_span`] (typically via the `deferred_span!` macro
/// family).
///
/// Materializing the span with [`enter`] calls [`Handler::try_enable`],
/// evaluates the argument factory, and emits [`Handler::enter_span`] if the
/// span is enabled. [`forget`] suppresses materialization, and [`into_handler`]
/// discards the span without materializing it.
///
/// # Argument capture
///
/// The lazy argument factory is invoked when the span is entered, and only if
/// [`Handler::try_enable`] returns `Some` at that point.
/// The `deferred_span!` macro expands to a `move` closure: non-`Copy` locals
/// referenced by the argument list are moved into the closure at macro
/// expansion, but the argument expressions themselves (function calls,
/// arithmetic, method calls) are evaluated lazily at enter time.
/// See [`deferred_span!`] for the full capture and evaluation rules.
///
/// [`enter`]: Self::enter
/// [`forget`]: Self::forget
/// [`into_handler`]: Self::into_handler
/// [`deferred_span!`]: crate::deferred_span!
/// [`Handler::try_enable`]: crate::Handler::try_enable
/// [`LoggerExt::deferred_span`]: crate::LoggerExt::deferred_span
#[must_use = "if unused, no span events will be emitted"]
#[derive(Eq, PartialEq, Ord, PartialOrd, Hash, Debug)]
pub struct DeferredSpan<H, LazyArgs>
where
    H: DynHandler<()>,
{
    handler: H,
    descriptor_and_lazy_args: Option<(&'static Descriptor, LazyArgs)>,
    parent_id: Option<SpanId>,
}

/// A deferred span context that owns a cloned handler and emits no events
/// until materialized.
///
/// `DetachedLogger` is produced by [`LoggerExt::detach`] to carry a span
/// context across threads, tasks, or lifetimes.
/// It captures the handler and the current [`SpanId`], and emits nothing on
/// creation or drop.
/// This makes it a cheap way to move a span context into `std::thread::spawn`
/// or `tokio::spawn` before the span's arguments are known.
///
/// `DetachedLogger` implements [`Logger`], so events logged through it are
/// attributed to the captured [`SpanId`].
/// A child span created via [`LoggerExt::borrowing_span`] is reported as
/// [`SpanKind::Detached`]: the span that created the context is not blocked
/// by the child and may emit events or be closed while the child is active.
/// That child's own children are reported as [`SpanKind::Nested`], because
/// their lifetimes are strictly contained within the child's lifetime.
///
/// [`LoggerExt::borrowing_span`]: crate::LoggerExt::borrowing_span
/// [`LoggerExt::detach`]: crate::LoggerExt::detach
#[must_use = "if unused, no span events will be emitted"]
#[derive(Eq, PartialEq, Ord, PartialOrd, Hash, Debug)]
pub struct DetachedLogger<H> {
    handler: H,
    parent_id: Option<SpanId>,
}

/// An [`OwningSpan`] whose handler is type-erased.
///
/// The primary use case is storing a span in a struct whose type cannot name
/// the concrete handler — a pattern that would otherwise force every struct
/// in the chain to carry `H: Handler<()>` bounds.
/// Dropping the struct drops the erased span and emits its exit event on the
/// boxed handler.
///
/// The erased handler carries `Send + Sync` bounds, so this alias can be used
/// in structs that cross threads or are captured by spawned tasks.
/// Construction requires the source handler to be `Send + Sync`, which is
/// always satisfied for handlers obtained via [`SharedHandler`]. Only the
/// low-level [`OwningSpan::new`] with a non-`Send` handler cannot be erased.
///
/// Constructed via [`OwningSpan::into_erased`].
#[cfg(feature = "alloc")]
#[cfg_attr(docsrs, doc(cfg(feature = "alloc")))]
pub type TypeErasedOwningSpan = OwningSpan<alloc::boxed::Box<dyn Send + Sync + DynHandler<()>>>;

/// An [`OwningSpan`] whose handler is type-erased and debuggable.
///
/// The primary use case is storing a span in a struct whose type cannot name
/// the concrete handler — a pattern that would otherwise force every struct
/// in the chain to carry `H: Handler<()>` bounds.
/// Dropping the struct drops the erased span and emits its exit event on the
/// boxed handler.
///
/// The erased handler carries `Send + Sync` bounds, so this alias can be used
/// in structs that cross threads or are captured by spawned tasks.
/// Construction requires the source handler to be `Send + Sync`, which is
/// always satisfied for handlers obtained via [`SharedHandler`].
/// Only the low-level [`OwningSpan::new`] with a non-`Send` handler cannot be
/// erased.
///
/// Constructed via [`OwningSpan::into_debuggable_erased`].
#[cfg(feature = "alloc")]
#[cfg_attr(docsrs, doc(cfg(feature = "alloc")))]
pub type DebuggableTypeErasedOwningSpan =
    OwningSpan<alloc::boxed::Box<dyn Send + Sync + crate::DebuggableDynHandler<()>>>;

impl SpanIdGenerator {
    /// Creates a new generator whose first generated ID is `1`.
    #[inline]
    #[must_use]
    pub const fn new() -> Self {
        Self(SpanIdGeneratorAtomic::new(1))
    }

    /// Generates a new [`SpanId`].
    ///
    /// The generator is a lock-free, relaxed atomic counter.
    /// It skips `0`, so the first generated ID is `1`, and after `u64::MAX` it
    /// wraps to `1` again.
    /// A single `SpanIdGenerator` therefore produces IDs that are unique within
    /// one full `u64` cycle — never exhausted in practice.
    ///
    /// On targets without 64-bit atomics it falls back to `u32` atomic counter.
    ///
    /// A handler that owns its own generator produces IDs unique only within
    /// that handler, which is the minimum [`BaseHandler`] requires.
    ///
    /// The uniqueness guarantee holds while the counter is advanced only by
    /// this method.
    /// The `test-util` feature exposes a way to write the counter directly,
    /// intended for tests that need to force a specific starting condition.
    /// After such a write, this method may return an ID that was recently
    /// generated.
    ///
    /// [`BaseHandler`]: crate::BaseHandler
    #[inline]
    #[must_use]
    pub fn generate(&self) -> SpanId {
        loop {
            let id = self.0.fetch_add(1, atomic::Ordering::Relaxed);
            #[cfg(not(target_has_atomic = "64"))]
            let id = u64::from(id);
            match NonZero::new(id) {
                Some(id) => return SpanId(id),
                None => core::hint::cold_path(),
            }
        }
    }

    /// Returns a shared reference to the underlying atomic counter.
    ///
    /// On targets with 64-bit atomics the returned type is `AtomicU64`.
    /// On targets without them it falls back to `AtomicU32`.
    ///
    /// # Test utility
    ///
    /// Exposed only with the `test-util` feature.
    /// It exists so that downstream test suites can inspect or modify the
    /// counter directly, for example to place it at a specific value before
    /// calling [`generate`].
    ///
    /// The uniqueness claim documented on [`generate`] assumes the counter
    /// is advanced only by that method.
    /// A caller that writes the counter can cause `generate` to return an
    /// ID that was already issued, which is exactly what some edge-case
    /// tests need to set up.
    ///
    /// [`generate`]: Self::generate
    #[cfg(feature = "test-util")]
    #[cfg_attr(docsrs, doc(cfg(feature = "test-util")))]
    #[inline]
    #[must_use]
    pub const fn as_inner(&self) -> &SpanIdGeneratorAtomic {
        &self.0
    }
}

impl Default for SpanIdGenerator {
    #[inline]
    fn default() -> Self {
        Self::new()
    }
}

impl<'a, H> BorrowingSpan<'a, H>
where
    H: ?Sized + DynHandler<()>,
{
    /// Creates a nested span from a borrowed handler and optional descriptor
    /// and span ID.
    ///
    /// # Span-kind contract
    ///
    /// This is a low-level constructor: it does not emit `enter_span` and does
    /// not establish any borrow relationship between the span and its parent.
    ///
    /// If `kind` is [`SpanKind::Nested`], the caller must guarantee that the
    /// parent does not emit events between this span's `enter_span` and
    /// `exit_span`.
    /// The type system does not enforce this for spans constructed directly.
    #[inline]
    pub const fn new(
        handler: &'a mut H,
        descriptor: Option<&'static Descriptor>,
        id: Option<SpanId>,
        kind: SpanKind,
    ) -> Self {
        Self {
            handler,
            descriptor,
            id,
            kind,
        }
    }

    /// Creates a transparent borrowing span that shares `parent_id` with its
    /// parent.
    ///
    /// The resulting span carries no descriptor and emits no enter/exit events,
    /// but events logged through it and child spans created from it are
    /// attributed to `parent_id`.
    ///
    /// # Span-kind contract
    ///
    /// `kind` is the [`SpanKind`] that the returned span reports for its own
    /// children.
    /// It must describe the relationship between those children and the span
    /// identified by `parent_id`:
    ///
    /// - [`SpanKind::Nested`] when `parent_id` names a span whose handler is
    ///   blocked by the `&mut H` borrow — a raw handler, or a real span created
    ///   on the same handler.
    /// - [`SpanKind::Detached`] when `parent_id` names a span whose handler is
    ///   a clone that the returned span also holds — a `DetachedLogger`, or
    ///   another transparent proxy that is itself `Detached`.
    ///
    /// Callers normally obtain the correct value from
    /// [`LoggerExt::child_borrowing_span_kind`] of the logger they call
    /// [`LoggerExt::transparent_borrowing_span`] on.
    /// That method already selects the right variant for both cases.
    ///
    /// [`LoggerExt::child_borrowing_span_kind`]: crate::Logger::child_borrowing_span_kind
    /// [`LoggerExt::transparent_borrowing_span`]: crate::LoggerExt::transparent_borrowing_span
    #[inline]
    pub const fn transparent(
        handler: &'a mut H,
        parent_id: Option<SpanId>,
        kind: SpanKind,
    ) -> Self {
        Self::new(handler, None, parent_id, kind)
    }

    /// Returns the static descriptor for this span, if any.
    #[inline]
    #[must_use]
    pub const fn descriptor(&self) -> Option<&'static Descriptor> {
        self.descriptor
    }

    /// Returns the span ID, if any.
    #[inline]
    #[must_use]
    pub const fn id(&self) -> Option<SpanId> {
        self.id
    }

    /// Returns the [`SpanKind`] this span reports to
    /// [`Handler::enter_span`] and [`DynHandler::exit_span`].
    ///
    /// The value describes this span's relationship to its creator — the
    /// entity identified by the `parent_span_id` argument that was passed
    /// to `enter_span` — not to spans created from it.
    /// To obtain the kind that a new child created from this span will
    /// report, use [`Logger::child_borrowing_span_kind`] instead.
    ///
    /// For a real (non-transparent) span, `child_borrowing_span_kind()` returns
    /// [`SpanKind::Nested`] regardless of `kind()`, because children
    /// borrow the span mutably and cannot outlive it.
    /// For a transparent span, `child_borrowing_span_kind()` returns `kind()`
    /// unchanged.
    ///
    /// [`Logger::child_borrowing_span_kind`]: crate::Logger::child_borrowing_span_kind
    /// [`Handler::enter_span`]: crate::Handler::enter_span
    /// [`DynHandler::exit_span`]: crate::DynHandler::exit_span
    /// [`SpanKind::Nested`]: crate::SpanKind::Nested.
    #[inline]
    #[must_use]
    pub const fn kind(&self) -> SpanKind {
        self.kind
    }

    /// Forgets the span, preventing its exit event from being emitted when
    /// dropped.
    ///
    /// `forget` is safe, analogous to [`core::mem::forget`]: it cannot cause
    /// undefined behavior or violate Rust's memory safety guarantees.
    /// But it prevents a cleanup step that would normally happen — here, the
    /// span's exit event — and leaves the affected bookkeeping in place.
    /// A backend that tracks open spans by [`SpanId`] retains the span as
    /// active indefinitely, leaking in long-running processes, and parent
    /// or child spans recorded around this span observe a
    /// lifetime-containment relationship that no longer matches
    /// [`SpanKind`]'s contract.
    ///
    /// Use `forget` only when its effect on the backend's view of the span tree
    /// is deliberate.
    #[inline]
    pub const fn forget(&mut self) {
        self.descriptor = None;
        // After `forget`, `kind` is only read by `child_borrowing_span_kind()`,
        // which uses it only for transparent spans.
        // Reset it so children of a forgotten span are `Nested`, as required by
        // the borrow relationship.
        self.kind = SpanKind::Nested;
    }

    /// Drops the span, emits its exit event if applicable, and returns the
    /// borrowed handler.
    #[inline]
    #[must_use]
    pub fn drop_into_handler(self) -> &'a mut H {
        if let Some(descriptor) = self.descriptor
            && let Some(span_id) = self.id
        {
            let handler = self.handler.borrow_mut();
            handler.exit_span(descriptor, span_id, self.kind, ());
        }

        // Do not add new field here without properly dropping them below.
        let Self {
            handler: _,
            descriptor: _,
            id: _,
            kind: _,
        } = &self;

        let this = ManuallyDrop::new(self);

        // SAFETY: `ManuallyDrop` never runs the inner destructor.
        // SAFETY: The read is performed once per field.
        unsafe {
            let handler = core::ptr::read(&raw const this.handler);
            let _ = this.descriptor; // `Copy` type.
            let _ = this.id; // `Copy` type.
            let _ = this.kind; // `Copy` type.
            handler
        }
    }
}

impl<H> OwningSpan<H>
where
    H: DynHandler<()>,
{
    /// Creates a span from an owned handler and optional descriptor and span
    /// ID.
    ///
    /// The span's own [`SpanKind`] is always [`SpanKind::Detached`], because
    /// an owning span never blocks its creator: it holds its own handler and
    /// the creator remains free to emit events and exit while this span is
    /// active.
    /// [`DynHandler::exit_span`] is emitted with that kind when the span is
    /// dropped.
    ///
    /// # Invariants
    ///
    /// This is a low-level constructor: it does not emit `enter_span`.
    /// The caller must have already called [`Handler::enter_span`] for this
    /// `span_id` with [`SpanKind::Detached`] so that the exit event produced
    /// on drop is paired with a matching entry.
    #[inline]
    pub const fn new(
        handler: H,
        descriptor: Option<&'static Descriptor>,
        id: Option<SpanId>,
    ) -> Self {
        Self {
            handler,
            descriptor,
            id,
        }
    }

    /// Creates a transparent owning span that shares `parent_id` with its
    /// parent.
    ///
    /// The resulting span carries no descriptor and emits no enter/exit events,
    /// but events logged through it and child spans created from it are
    /// attributed to `parent_id`.
    ///
    /// Child spans created from the returned span are always reported as
    /// [`SpanKind::Detached`], because the owning span holds its own handler
    /// and the span identified by `parent_id` is therefore not blocked by
    /// those children.
    /// This matches every other owning span: an owning span never blocks its
    /// creator, so any span created under it — directly, or through a
    /// transparent proxy — is `Detached` relative to the original parent.
    ///
    /// Use [`OwningSpan::transparent`] to propagate a span ID across a
    /// boundary without emitting lifecycle events.
    /// Use [`BorrowingSpan::transparent`] when the borrow itself should block
    /// the parent.
    #[inline]
    pub const fn transparent(handler: H, parent_id: Option<SpanId>) -> Self {
        Self::new(handler, None, parent_id)
    }

    /// Returns the static descriptor for this span, if any.
    #[inline]
    #[must_use]
    pub const fn descriptor(&self) -> Option<&'static Descriptor> {
        self.descriptor
    }

    /// Returns the span ID, if any.
    #[inline]
    #[must_use]
    pub const fn id(&self) -> Option<SpanId> {
        self.id
    }

    /// Consumes the span and returns its type-erased form.
    ///
    /// The returned [`TypeErasedOwningSpan`] owns the same handler (boxed), the
    /// same [`Descriptor`], [`SpanId`], and [`SpanKind`], but narrows the
    /// handler to `dyn DynHandler<()> + Send + Sync`. Dropping the erased
    /// span emits the same [`DynHandler::exit_span`] as dropping the original
    /// would.
    ///
    /// This is the primary way to store an owning span in a struct without
    /// carrying the concrete handler type as a generic parameter.
    #[cfg(feature = "alloc")]
    #[cfg_attr(docsrs, doc(cfg(feature = "alloc")))]
    #[inline]
    pub fn into_erased(mut self) -> TypeErasedOwningSpan
    where
        H: 'static + Send + Sync,
    {
        let descriptor = self.descriptor.take();
        let id = self.id;
        let handler = alloc::boxed::Box::new(self.drop_into_handler());

        TypeErasedOwningSpan {
            handler,
            descriptor,
            id,
        }
    }

    /// Consumes the span and returns its type-erased form with a [`Debug`]able
    /// handler.
    ///
    /// The returned [`DebuggableTypeErasedOwningSpan`] owns the same handler
    /// (boxed), the same [`Descriptor`], [`SpanId`], and [`SpanKind`], but
    /// narrows the handler to `dyn DynHandler<()> + Send + Sync`. Dropping
    /// the erased span emits the same [`DynHandler::exit_span`] as dropping
    /// the original would.
    ///
    /// This is the primary way to store an owning span in a struct without
    /// carrying the concrete handler type as a generic parameter.
    #[cfg(feature = "alloc")]
    #[cfg_attr(docsrs, doc(cfg(feature = "alloc")))]
    #[inline]
    pub fn into_debuggable_erased(mut self) -> DebuggableTypeErasedOwningSpan
    where
        H: 'static + Send + Sync + Debug,
    {
        let descriptor = self.descriptor.take();
        let id = self.id;
        let handler = alloc::boxed::Box::new(self.drop_into_handler());

        DebuggableTypeErasedOwningSpan {
            handler,
            descriptor,
            id,
        }
    }

    /// Forgets the span, preventing its exit event from being emitted when
    /// dropped.
    ///
    /// `forget` is safe, analogous to [`core::mem::forget`]: it cannot cause
    /// undefined behavior or violate Rust's memory safety guarantees.
    /// But it prevents a cleanup step that would normally happen — here, the
    /// span's exit event — and leaves the affected bookkeeping in place.
    /// A backend that tracks open spans by [`SpanId`] retains the span as
    /// active indefinitely, leaking in long-running processes, and parent
    /// or child spans recorded around this span observe a
    /// lifetime-containment relationship that no longer matches
    /// [`SpanKind`]'s contract.
    ///
    /// Use `forget` only when its effect on the backend's view of the span tree
    /// is deliberate.
    #[inline]
    pub const fn forget(&mut self) {
        self.descriptor = None;
    }

    /// Drops the span, emits its exit event if applicable, and returns the
    /// owned handler.
    #[inline]
    #[must_use]
    pub fn drop_into_handler(mut self) -> H {
        if let Some(descriptor) = self.descriptor
            && let Some(span_id) = self.id
        {
            let handler = self.handler.borrow_mut();
            handler.exit_span(descriptor, span_id, SpanKind::Detached, ());
        }

        // Do not add new field here without properly dropping them below.
        let Self {
            handler: _,
            descriptor: _,
            id: _,
        } = &self;

        let this = ManuallyDrop::new(self);

        // SAFETY: `ManuallyDrop` never runs the inner destructor.
        // SAFETY: The read is performed once per field.
        unsafe {
            let handler = core::ptr::read(&raw const this.handler);
            let _ = this.descriptor; // `Copy` type.
            let _ = this.id; // `Copy` type.
            handler
        }
    }
}

impl<H, LazyArgs> DeferredSpan<H, LazyArgs>
where
    H: Handler<()>,
{
    /// Creates a deferred span from an owned handler, a descriptor, a lazy
    /// argument factory, and an optional parent span ID.
    ///
    /// The argument factory is invoked at [`enter`] time, so any expression
    /// evaluation or side effects it triggers are deferred along with the span
    /// itself.
    ///
    /// [`enter`]: Self::enter
    #[inline]
    pub const fn new(
        handler: H,
        descriptor: &'static Descriptor,
        lazy_args: LazyArgs,
        parent_id: Option<SpanId>,
    ) -> Self {
        Self {
            handler,
            descriptor_and_lazy_args: Some((descriptor, lazy_args)),
            parent_id,
        }
    }

    /// Returns the static descriptor for this span, if any.
    #[inline]
    #[must_use]
    pub const fn descriptor(&self) -> Option<&'static Descriptor> {
        match self.descriptor_and_lazy_args {
            Some((descriptor, _)) => Some(descriptor),
            None => None,
        }
    }

    /// Returns the parent span ID, or `None` if the logger this span was
    /// created from was not associated with a span.
    #[inline]
    #[must_use]
    pub const fn parent_id(&self) -> Option<SpanId> {
        self.parent_id
    }

    /// Materializes the span with [`SpanKind::Detached`] and returns an
    /// [`OwningSpan`] that emits [`DynHandler::exit_span`] on drop.
    ///
    /// If [`Handler::try_enable`] returns `None`, or [`forget`] has been
    /// called, no events are emitted and the returned [`OwningSpan`]
    /// is transparent: it propagates the parent [`SpanId`] to events and
    /// child spans but emits no enter/exit events of its own.
    ///
    /// # Span kind
    ///
    /// The materialized span is always reported as [`SpanKind::Detached`],
    /// never [`SpanKind::Nested`].
    /// A [`DeferredSpan`] owns a cloned handler, so the span that created it
    /// is not blocked and may emit events or be closed while the materialized
    /// span is active. Reporting `Detached` is the only kind compatible with
    /// that relationship.
    ///
    /// To obtain a strictly nested span, materialize the span on the same
    /// thread as its parent via [`LoggerExt::borrowing_span`], which returns a
    /// [`BorrowingSpan`] whose lifetime the borrow checker ties to the parent.
    ///
    /// If the span is disabled (either because `try_enable` returns `None` or
    /// `forget` was called), the returned `OwningSpan` is transparent.
    /// Its `child_borrowing_span_kind()` therefore returns
    /// `SpanKind::Detached`, matching the enabled branch: a `DeferredSpan`
    /// holds a cloned handler and cannot produce a `Nested` child that blocks
    /// the original parent.
    ///
    /// [`LoggerExt::borrowing_span`]: crate::LoggerExt::borrowing_span
    /// [`forget`]: Self::forget
    #[inline]
    pub fn enter<'a, Args>(mut self) -> OwningSpan<H>
    where
        LazyArgs: FnOnce() -> Args,
        Args: LogArgs<'a>,
    {
        if let Some((descriptor, lazy_args)) = self.descriptor_and_lazy_args
            && let Some(context) = self.handler.try_enable(descriptor, ())
        {
            let span_id = self.handler.generate_span_id();
            self.handler.enter_span(
                descriptor,
                (lazy_args)(),
                self.parent_id,
                span_id,
                SpanKind::Detached,
                context,
            );
            OwningSpan::new(self.handler, Some(descriptor), Some(span_id))
        } else {
            OwningSpan::transparent(self.handler, self.parent_id)
        }
    }

    /// Suppresses span events on materialization.
    ///
    /// After this call, [`enter`] returns a transparent [`OwningSpan`] that
    /// propagates the parent [`SpanId`] to events and child spans but emits no
    /// enter/exit events of its own.
    ///
    /// [`enter`]: Self::enter
    #[inline]
    pub fn forget(&mut self) {
        self.descriptor_and_lazy_args = None;
    }

    /// Discards the deferred span without materializing it and returns the
    /// owned handler.
    #[inline]
    #[must_use]
    pub fn into_handler(self) -> H {
        self.handler
    }
}

impl<H> DetachedLogger<H>
where
    H: SharedHandler<()>,
{
    /// Creates a detached context from an owned handler and an optional parent
    /// span ID.
    #[inline]
    pub const fn new(handler: H, parent_id: Option<SpanId>) -> Self {
        Self { handler, parent_id }
    }

    /// Creates a detached context from a cloned handler and no parent span ID.
    #[inline]
    pub const fn transparent(handler: H) -> Self {
        Self::new(handler, None)
    }

    /// Returns the parent span ID, or `None` for a root context.
    #[inline]
    pub const fn parent_id(&self) -> Option<SpanId> {
        self.parent_id
    }

    /// Discards the context and returns the owned handler.
    #[inline]
    pub fn into_handler(self) -> H {
        self.handler
    }
}

impl<H> Drop for BorrowingSpan<'_, H>
where
    H: ?Sized + DynHandler<()>,
{
    #[inline]
    fn drop(&mut self) {
        if let Some(descriptor) = self.descriptor
            && let Some(span_id) = self.id
        {
            self.handler.exit_span(descriptor, span_id, self.kind, ());
        }
    }
}

impl<H> Drop for OwningSpan<H>
where
    H: DynHandler<()>,
{
    #[inline]
    fn drop(&mut self) {
        if let Some(descriptor) = self.descriptor
            && let Some(span_id) = self.id
        {
            self.handler
                .exit_span(descriptor, span_id, SpanKind::Detached, ());
        }
    }
}

impl<H> Logger for BorrowingSpan<'_, H>
where
    H: SharedHandler<()>,
{
    type Handler = H;

    #[inline]
    fn handler_ref(&self) -> &Self::Handler {
        &*self.handler
    }

    #[inline]
    fn handler_mut(&mut self) -> &mut Self::Handler {
        &mut *self.handler
    }

    #[inline]
    fn span_id(&self) -> Option<SpanId> {
        self.id
    }

    #[inline]
    fn child_borrowing_span_kind(&self) -> SpanKind {
        if self.descriptor.is_none() {
            // Transparent span: a pass-through proxy.
            // Propagate the inherited kind so a proxy created from a
            // `DetachedLogger` still produces `Detached` children.
            self.kind
        } else {
            // Real span: children borrow `self` mutably, so they cannot outlive
            // it and `self` cannot emit events while they are active.
            SpanKind::Nested
        }
    }
}

impl<H> Logger for OwningSpan<H>
where
    H: SharedHandler<()>,
{
    type Handler = H;

    #[inline]
    fn handler_ref(&self) -> &Self::Handler {
        &self.handler
    }

    #[inline]
    fn handler_mut(&mut self) -> &mut Self::Handler {
        &mut self.handler
    }

    #[inline]
    fn span_id(&self) -> Option<SpanId> {
        self.id
    }

    #[inline]
    fn child_borrowing_span_kind(&self) -> SpanKind {
        if self.descriptor.is_none() {
            // Transparent owning span is detached from its parent, so its
            // child span kind is `Detached`.
            SpanKind::Detached
        } else {
            // Real span: children borrow `self` mutably, so they cannot outlive
            // it and `self` cannot emit events while they are active.
            SpanKind::Nested
        }
    }
}

impl<H> Logger for DetachedLogger<H>
where
    H: SharedHandler<()>,
{
    type Handler = H;

    #[inline]
    fn handler_ref(&self) -> &Self::Handler {
        &self.handler
    }

    #[inline]
    fn handler_mut(&mut self) -> &mut Self::Handler {
        &mut self.handler
    }

    #[inline]
    fn span_id(&self) -> Option<SpanId> {
        self.parent_id
    }

    #[inline]
    fn child_borrowing_span_kind(&self) -> SpanKind {
        // The context is a proxy for a span living elsewhere.
        // The span that produced the context is not blocked by children created
        // here, so children are `Detached` from the parent's perspective.
        SpanKind::Detached
    }
}

/// Formats the span ID as its numeric value, without a prefix or the
/// `SpanId(...)` wrapper that [`Debug`] prints.
impl Display for SpanId {
    #[inline]
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        Display::fmt(&self.0, f)
    }
}

#[cfg(test)]
mod tests {
    use alloc::format;
    use core::num::NonZero;
    use core::sync::atomic;

    use crate::{SpanId, SpanIdGenerator};

    macro_rules! non_zero {
        ($value:expr) => {
            const { NonZero::new($value).unwrap() }
        };
    }

    #[test]
    fn test_span_id_fmt() {
        assert_eq!(format!("{}", SpanId(non_zero!(123))), "123");
        assert_eq!(format!("{:?}", SpanId(non_zero!(123))), "SpanId(123)");
    }

    #[test]
    fn test_span_id_generator() {
        assert_eq!(SpanIdGenerator::new().generate(), SpanId(non_zero!(1)));
        assert_eq!(SpanIdGenerator::default().generate(), SpanId(non_zero!(1)));

        let exhausted_generator = SpanIdGenerator::new();
        exhausted_generator
            .0
            .store(u64::MAX - 1, atomic::Ordering::Relaxed);
        assert_eq!(
            exhausted_generator.generate(),
            SpanId(non_zero!(u64::MAX - 1))
        );
        assert_eq!(exhausted_generator.generate(), SpanId(non_zero!(u64::MAX)));
        assert_eq!(exhausted_generator.generate(), SpanId(non_zero!(1)));
        assert_eq!(exhausted_generator.generate(), SpanId(non_zero!(2)));
        assert_eq!(exhausted_generator.generate(), SpanId(non_zero!(3)));

        #[cfg(feature = "test-util")]
        assert_eq!(
            exhausted_generator
                .as_inner()
                .load(atomic::Ordering::Relaxed),
            4
        );
    }
}
